prompt --application/shared_components/logic/application_processes/log_logout
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(15511405644718186019)
,p_process_sequence=>1
,p_process_point=>'ON_NEW_INSTANCE'
,p_process_name=>'LOG_LOGOUT'
,p_static_id=>'log-logout'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE LOGIN_AUDIT_LOG',
'    SET LOGOUT_TIME = SYSDATE,',
'        ACTION      = ''LOGOUT''',
'    WHERE USERNAME    = UPPER(:APP_USER)',
'      AND ACTION      = ''LOGIN''',
'      AND LOGOUT_TIME IS NULL;',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'Request = LOGOUT'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_version_scn=>'SH256:mV9UCmPRTojIEg0fuCLSFLVljj_wMbdhs2Gf7LOPIMg'
