begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(29313075232656431334)
,p_name=>'Notify_Study_Ending'
,p_static_id=>'notify-study-ending'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=12;BYMINUTE=0'
,p_polling_status=>'ACTIVE'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    S.PLAN_ID,',
'    P.PRODUCT_NAME,',
'    S.BATCH_NO,',
'    S.SHELF_NO,',
'    S.PLAN_PULLOUT_DATE,',
'    S.STUDY_TYPE',
'FROM STABILITY_WHOLE_PLAN S',
'LEFT JOIN PRODUCTS P ON S.PRODUCT_ID = P.PRODUCT_ID',
'WHERE S.PULLOUT_STATUS = ''PENDING''',
'  AND S.IS_DELETED = ''N''',
'  AND S.PLAN_PULLOUT_DATE BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + 3'))
,p_commit_each_row=>false
,p_error_handling_type=>'ABORT'
