wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14799642175515810738)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_static_id=>'new'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'BEGIN',
'',
'    SELECT FULL_NAME, USERNAME, ROLE, USER_ID, EMAIL',
'    INTO :P1_FULL_NAME, :P1_USER_NAME, :P1_ROLE, :P1_USER_ID, :P1_EMAIL',
'    FROM APP_USERS',
'    WHERE UPPER(USERNAME) = UPPER(:APP_USER);',
'',
unistr('    -- \062D\0633\0627\0628 \0627\0644\062D\0631\0648\0641 \0627\0644\0623\0648\0644\0649 (Initials)'),
'    SELECT UPPER(',
'             SUBSTR(REGEXP_SUBSTR(:P1_FULL_NAME, ''^\S+''), 1, 1) ||',
'             NVL(SUBSTR(REGEXP_SUBSTR(:P1_FULL_NAME, ''\S+$''), 1, 1), '''')',
'           )',
'    INTO :P1_INITIALS',
'    FROM DUAL;',
'',
'    BEGIN',
'        SELECT TO_CHAR(MAX(LOGIN_TIME), ''DD-MON-YYYY HH24:MI'')',
'        INTO :P1_LAST_LOGIN',
'        FROM LOGIN_AUDIT_LOG',
'        WHERE UPPER(USERNAME) = UPPER(:APP_USER)',
'          AND ACTION = ''LOGIN''',
'          AND LOGIN_TIME < (',
'              SELECT MAX(LOGIN_TIME)',
'              FROM LOGIN_AUDIT_LOG',
'              WHERE UPPER(USERNAME) = UPPER(:APP_USER)',
'                AND ACTION = ''LOGIN''',
'          );',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            :P1_LAST_LOGIN := ''First login'';',
'    END;',
'',
unistr('    -- \0628\0646\0627\0621 \0642\0627\0626\0645\0629 Recent Activity'),
'    FOR rec IN (',
'        SELECT TABLE_NAME, ACTION_TYPE, RECORD_ID, CHANGE_DATE,',
'               TRUNC(SYSDATE - CHANGE_DATE) AS days_ago,',
'               ROUND((SYSDATE - CHANGE_DATE) * 24) AS hours_ago',
'        FROM STABILITY_AUDIT_LOG',
'        ORDER BY CHANGE_DATE DESC',
'        FETCH FIRST 3 ROWS ONLY',
'    ) LOOP',
'        v_html := v_html ||',
'            ''<div style="display:flex; justify-content:space-between; padding:8px 0; border-bottom:0.5px solid #ddd; font-size:13px;">'' ||',
unistr('            ''<span>'' || rec.TABLE_NAME || '' \2014 '' || rec.ACTION_TYPE || '' (ID: '' || rec.RECORD_ID || '')</span>'' ||'),
'            ''<span style="color:#999;">'' ||',
'                CASE',
'                    WHEN rec.hours_ago < 1 THEN ''just now''',
'                    WHEN rec.hours_ago < 24 THEN rec.hours_ago || '' hours ago''',
'                    ELSE rec.days_ago || '' days ago''',
'                END ||',
'            ''</span></div>'';',
'    END LOOP;',
'',
'    :P1_RECENT_ACTIVITY := v_html;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P1_FULL_NAME := :APP_USER;',
'        :P1_INITIALS := ''NA'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>14799642175515810738
,p_created_on=>wwv_flow_imp.dz('20260709054457Z')
,p_updated_on=>wwv_flow_imp.dz('20260709072926Z')
,p_created_by=>'NOURHASAN0002@GMAIL.COM'
,p_updated_by=>'NOURHASAN0002@GMAIL.COM'
);
end;
