wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19341317611521465826)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>' Insert Plan By Study Type'
,p_static_id=>'insert-plan-by-study-type'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    TYPE T_MONTHS IS TABLE OF NUMBER;',
'    V_MONTHS T_MONTHS := T_MONTHS();',
'    V_MFG_DATE DATE;',
'    V_INCUBATION_DATE DATE;',
'BEGIN',
unistr('    -- \062A\062D\0648\064A\0644 \0627\0644\062A\0627\0631\064A\062E \0645\0646 MON-YY \0644\0640 DATE'),
'    V_MFG_DATE := TO_DATE(''01-'' || :P4_MFG_DATE, ''DD-MON-YY'');',
'    V_INCUBATION_DATE := TO_DATE(:P4_INCUBATION_DATE, ''DD-MON-YY'');',
'',
'    IF :P4_STUDY_TYPE = ''LONG_TERM'' THEN',
'        V_MONTHS := T_MONTHS(3,6,9,12,18,24,36,48,60);',
'    ELSIF :P4_STUDY_TYPE = ''ACCELERATED'' THEN',
'        V_MONTHS := T_MONTHS(3,6);',
'    ELSIF :P4_STUDY_TYPE = ''ONGOING'' THEN',
'        V_MONTHS := T_MONTHS(3,6,12,18,24,36,48,60);',
'    ',
'        RAISE_APPLICATION_ERROR(-20010, ''Unknown study type: '' || :P4_STUDY_TYPE);',
'    END IF;',
'',
'    FOR I IN 1..V_MONTHS.COUNT LOOP',
'        INSERT INTO STABILITY_WHOLE_PLAN (',
'            PRODUCT_ID, BATCH_NO, MFG_DATE,',
'            INTERVAL_MONTHS, CHAMBER_ID, SHELF_NO,',
'            QUANTITY, INCUBATION_DATE,',
'            PULLOUT_STATUS, STUDY_STATUS,',
'            STUDY_TYPE, REMARK, IS_DELETED',
'        ) VALUES (',
'            :P4_PRODUCT_ID, :P4_BATCH_NO, V_MFG_DATE,',
'            V_MONTHS(I), :P4_CHAMBER_ID, :P4_SHELF_NO,',
'            :P4_QUANTITY, V_INCUBATION_DATE,',
'            ''PENDING'', ''ONGOING'',',
'            :P4_STUDY_TYPE, :P4_REMARK, ''N''',
'        );',
'    END LOOP;',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>19341317611521465826
,p_created_on=>wwv_flow_imp.dz('20260719060240Z')
,p_updated_on=>wwv_flow_imp.dz('20260927120700Z')
,p_created_by=>'NOURHASAN0002@GMAIL.COM'
,p_updated_by=>'NOURHASAN0002@GMAIL.COM'
);
