'BEGIN',
'    :P4_CHAMBER_ID := REGEXP_SUBSTR(:P4_SHELF_NO, ''^[^-]+-[^-]+'');',
'    ',
'    SELECT CONDITION INTO :P4_CONDITION',
'    FROM CHAMBERS',
